function Krypton:makev2address(key)
  local protein = {}
  local stick = sha256(sha256(key))
  local n = 0
  local link = 0
  local v2 = "k"
  if self.currency and self.currency.address_prefix then
    v2 = self.currency.address_prefix
  end
  repeat
