---@param canvas PixelCanvas
---@param text string
---@param x integer
---@param y integer
---@param c integer
function Font:writeRight(canvas, text, x, y, c)
    local width = self:getWidth(text)
    self:write(canvas, text, x - width + 1, y, c)
end

