        currencySymbol = "tst"
    end
    if currencySymbol:lower() == "kst" and (layout == "medium" or layout == "small") then
        currencySymbol = "kst"
    elseif currencySymbol:lower() == "kst" then
        currencySymbol = "\164"
    end
